import math
from fractions import Fraction as F
def rising(v,n):return math.prod(v+i for i in range(n))
def cv(g,a,b):return[math.comb(g,j)*(-1)**(g-j)*rising(a,g-j)*rising(b-a,j)for j in range(g+1)]
def pv(g,a,m,b):
 c=cv(g,a,b);return[m*c[0]]+[(m+j)*c[j]+(m+j-1-g)*c[j-1]for j in range(1,g+1)]+[m*c[g]]
def col(g,a,m,b):
 d=1-g-a-m;s=-a-g if d>0 else -a-g+abs(d);z=1 if d>0 else -1
 return{s+j:z*x for j,x in enumerate(pv(g,a,m,b))if x}
def comp(g,k,q,b):
 c=1-g;return[col(g,a,m,b)for a in range(0,2*k+1,2)for m in(c-q-a,c+q-a)]
def defect(g,a,q,b):
 c=cv(g,a,b);J=[c[0]]+[c[j]+c[j-1]for j in range(1,g+1)]+[c[g]];o={}
 for s,z in((-a-g,-2),(-a-g+q+2,2)):
  for j,x in enumerate(J):o[s+j]=o.get(s+j,0)+z*x
 return{r:x for r,x in o.items()if x}
def rank(C):
